shell_commands.command:
cd /testbed && git apply <<'PATCH'
diff --git a/tokio-util/tests/time_delay_queue.rs b/tokio-util/tests/time_delay_queue.rs
--- a/tokio-util/tests/time_delay_queue.rs
+++ b/tokio-util/tests/time_delay_queue.rs
@@ -171,6 +171,34 @@ async fn remove_entry() {
     assert!(entry.is_none());
 }

+#[tokio::test(start_paused = true)]
+async fn remove_last_entry_wakes_poller() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let key = queue.insert("foo", Duration::from_secs(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    let entry = queue.remove(&key);
+    assert_eq!(entry.into_inner(), "foo");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test(start_paused = true)]
+async fn try_remove_last_entry_wakes_poller() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let key = queue.insert("foo", Duration::from_secs(100));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    let entry = queue.try_remove(&key).unwrap();
+    assert_eq!(entry.into_inner(), "foo");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
 #[tokio::test]
 async fn reset_entry() {
     time::pause();
PATCH
cargo test -p tokio-util --features full --test time_delay_queue remove_last_entry --offline

